// Written with the help of Claude
// AI Usage Note: generated by Claude; every case checked against EventImportService by running the tests.
import assert from 'node:assert/strict';
import { describe, mock, test } from 'node:test';
import type { EventProvider } from '../../dist/core/catalog/adapters/event-provider.js';
import type { EventsRepository } from '../../dist/core/catalog/repositories/events.repository.js';
import type { VenuesRepository } from '../../dist/core/catalog/repositories/venues.repository.js';
import { EventImportService } from '../../dist/core/catalog/services/event-import.service.js';
import type { CategoriesService } from '../../dist/core/catalog/services/categories.service.js';
import type { Category } from '../../dist/core/catalog/types/category.js';
import type { Event, EventChanges } from '../../dist/core/catalog/types/event.js';
import type { ImportedEvent, ImportedEventRecord, NormalizeResult } from '../../dist/core/catalog/types/import.js';
import type { NewImportedVenue, Venue } from '../../dist/core/catalog/types/venue.js';
import { aCategory, anEvent, aVenue, CATEGORY_ID, VENUE_ID } from './fixtures/catalog.ts';

const PROVIDER_ID = 'test_provider';

function anImportedEvent(overrides: Partial<ImportedEvent> = {}): ImportedEvent {
  return {
    externalId: 'ext-1',
    title: 'Jazz evening',
    description: 'Live quartet.',
    categoryName: 'Exhibitions',
    venue: { name: 'Caribbean Club', address: 'Kyiv', location: { lat: 50.46, lng: 30.52 } },
    startsAt: '2026-10-22T16:00:00.000Z',
    endsAt: '2026-10-22T19:00:00.000Z',
    ...overrides,
  };
}

/** The Event that anImportedEvent() becomes once saved, so a second run finds nothing to change. */
function theSavedEvent(overrides: Partial<Event> = {}): Event {
  return anEvent({
    id: 'e0000000-0000-4000-8000-0000000000aa',
    title: 'Jazz evening',
    description: 'Live quartet.',
    venue: aVenue({ organizationId: null }),
    startsAt: '2026-10-22T19:00:00+03:00',
    endsAt: '2026-10-22T22:00:00+03:00',
    source: 'import',
    organizationId: null,
    ...overrides,
  });
}

/** Every dependency of EventImportService as a mock; a test changes only what it needs. */
function makeService(raws: unknown[] = [{}], normalized: NormalizeResult[] = [{ event: anImportedEvent() }]) {
  const normalize = mock.fn((): NormalizeResult => ({ skip: { externalId: null, reason: 'unset' } }));
  normalized.forEach((result, call) => normalize.mock.mockImplementationOnce(() => result, call));
  const provider = { id: PROVIDER_ID, fetch: mock.fn(() => Promise.resolve(raws)), normalize };
  const eventsRepository = {
    findByExternalId: mock.fn((): Promise<Event | undefined> => Promise.resolve(undefined)),
    createImported: mock.fn((record: ImportedEventRecord): Promise<Event> => Promise.resolve(anEvent({ ...record }))),
    update: mock.fn((id: string, changes: EventChanges) => Promise.resolve({ ...anEvent({ id }), ...changes })),
  };
  const venuesRepository = {
    findImported: mock.fn((): Promise<Venue | undefined> => Promise.resolve(undefined)),
    createImported: mock.fn((venue: NewImportedVenue): Promise<Venue> => Promise.resolve(aVenue({ ...venue }))),
  };
  const categoriesService = {
    listActive: mock.fn((): Promise<Category[]> => Promise.resolve([aCategory()])),
  };

  const service = new EventImportService(
    provider as unknown as EventProvider,
    eventsRepository as unknown as EventsRepository,
    venuesRepository as unknown as VenuesRepository,
    categoriesService as unknown as CategoriesService,
  );
  return { service, provider, eventsRepository, venuesRepository, categoriesService };
}

// FR-008, FLEX-003
describe('EventImportService.run', () => {
  test('saves a new event as an imported, published event without an organization', async () => {
    const { service, eventsRepository } = makeService();

    const report = await service.run();

    assert.deepEqual(eventsRepository.createImported.mock.calls[0]?.arguments[0], {
      title: 'Jazz evening',
      description: 'Live quartet.',
      categoryId: CATEGORY_ID,
      venueId: VENUE_ID,
      startsAt: '2026-10-22T16:00:00.000Z',
      endsAt: '2026-10-22T19:00:00.000Z',
      source: 'import',
      status: 'published',
      organizationId: null,
      provider: PROVIDER_ID,
      externalId: 'ext-1',
    });
    assert.deepEqual(report, {
      provider: PROVIDER_ID,
      fetched: 1,
      created: 1,
      updated: 0,
      unchanged: 0,
      skipped: [],
    });
  });

  test('creates the venue when it is not known yet', async () => {
    const { service, venuesRepository } = makeService();

    await service.run();

    assert.deepEqual(venuesRepository.createImported.mock.calls[0]?.arguments, [anImportedEvent().venue]);
  });

  test('reuses a venue an earlier import created', async () => {
    const { service, venuesRepository, eventsRepository } = makeService();
    venuesRepository.findImported.mock.mockImplementation(() => Promise.resolve(aVenue({ id: 'known-venue' })));

    await service.run();

    assert.equal(venuesRepository.createImported.mock.callCount(), 0);
    assert.equal(eventsRepository.createImported.mock.calls[0]?.arguments[0].venueId, 'known-venue');
  });

  test('matches the category name without regard to case', async () => {
    const { service, eventsRepository } = makeService(
      [{}],
      [{ event: anImportedEvent({ categoryName: 'EXHIBITIONS' }) }],
    );

    await service.run();

    assert.equal(eventsRepository.createImported.mock.calls[0]?.arguments[0].categoryId, CATEGORY_ID);
  });

  test('looks the event up by provider and external id, so an organization event is never touched', async () => {
    const { service, eventsRepository } = makeService();

    await service.run();

    assert.deepEqual(eventsRepository.findByExternalId.mock.calls[0]?.arguments, [PROVIDER_ID, 'ext-1']);
  });

  test('leaves an event the provider has not changed', async () => {
    const { service, eventsRepository } = makeService();
    eventsRepository.findByExternalId.mock.mockImplementation(() =>
      Promise.resolve(theSavedEvent({ venue: aVenue({ organizationId: null }) })),
    );

    const report = await service.run();

    assert.equal(eventsRepository.createImported.mock.callCount(), 0);
    assert.equal(eventsRepository.update.mock.callCount(), 0);
    assert.deepEqual([report.created, report.updated, report.unchanged], [0, 0, 1]);
  });

  test('updates an event whose title the provider changed', async () => {
    const { service, eventsRepository } = makeService(
      [{}],
      [{ event: anImportedEvent({ title: 'Jazz evening, new date' }) }],
    );
    eventsRepository.findByExternalId.mock.mockImplementation(() => Promise.resolve(theSavedEvent()));

    const report = await service.run();

    const [id, changes] = eventsRepository.update.mock.calls[0]?.arguments ?? [];
    assert.equal(id, theSavedEvent().id);
    assert.equal(changes?.title, 'Jazz evening, new date');
    assert.deepEqual([report.created, report.updated, report.unchanged], [0, 1, 0]);
  });

  test('skips a record with an unknown category and saves nothing for it', async () => {
    const { service, eventsRepository, venuesRepository } = makeService(
      [{}],
      [{ event: anImportedEvent({ categoryName: 'Comedy' }) }],
    );

    const report = await service.run();

    assert.deepEqual(report.skipped, [{ externalId: 'ext-1', reason: 'Unknown category "Comedy"' }]);
    assert.equal(eventsRepository.createImported.mock.callCount(), 0);
    assert.equal(venuesRepository.createImported.mock.callCount(), 0);
  });

  const badTimes = [
    { title: 'an event that ends before it starts', endsAt: '2026-10-22T15:00:00.000Z' },
    { title: 'an event that ends when it starts', endsAt: '2026-10-22T16:00:00.000Z' },
  ];
  for (const { title, endsAt } of badTimes) {
    test(`skips ${title}`, async () => {
      const { service, eventsRepository } = makeService([{}], [{ event: anImportedEvent({ endsAt }) }]);

      const report = await service.run();

      assert.equal(report.skipped[0]?.reason, 'The event does not end after it starts');
      assert.equal(eventsRepository.createImported.mock.callCount(), 0);
    });
  }

  test('reports a record the adapter skipped and still imports the others', async () => {
    const { service, eventsRepository } = makeService(
      [{}, {}],
      [
        { skip: { externalId: 'bad-1', reason: 'Invalid record: title' } },
        { event: anImportedEvent({ externalId: 'ext-2' }) },
      ],
    );

    const report = await service.run();

    assert.deepEqual(report.skipped, [{ externalId: 'bad-1', reason: 'Invalid record: title' }]);
    assert.equal(report.created, 1);
    assert.equal(eventsRepository.createImported.mock.calls[0]?.arguments[0].externalId, 'ext-2');
  });

  test('imports nothing from an empty feed', async () => {
    const { service } = makeService([], []);

    assert.deepEqual(await service.run(), {
      provider: PROVIDER_ID,
      fetched: 0,
      created: 0,
      updated: 0,
      unchanged: 0,
      skipped: [],
    });
  });

  test('lets a failing fetch stop the run, so the catalog keeps the last imported events (FR-014)', async () => {
    const { service, provider, eventsRepository } = makeService();
    provider.fetch.mock.mockImplementation(() => Promise.reject(new Error('Concert.ua is down')));

    await assert.rejects(service.run(), /Concert\.ua is down/);

    assert.equal(eventsRepository.createImported.mock.callCount(), 0);
  });
});
